begin;
-- Testtransport avstängd i denna rollback-transaktion: inga riktiga push/SMS/mejl.
update public.vihem_system_settings set value=jsonb_set(value,'{enabled}','false') where key='push_notification_dispatch';
create function pg_temp.expect(label text,ok boolean) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.reject(label text,statement text) returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;if not failed then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create temp table f(org uuid,other_org uuid,staff uuid,admin uuid,other_admin uuid,revision text);
do $$declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();s uuid:=gen_random_uuid();a uuid:=gen_random_uuid();a2 uuid:=gen_random_uuid();begin
 insert into public.vihem_organisations(id,name,slug) values(o,'QA Notification','qa-notif-'||o),(o2,'QA Other Notification','qa-notif-'||o2);
 insert into auth.users(id,email) values(s,s||'@example.invalid'),(a,a||'@example.invalid'),(a2,a2||'@example.invalid');
 insert into public.vihem_profiles(id,organisation_id,name,email,role,active) values(s,o,'QA Staff',s||'@example.invalid','staff',true),(a,o,'QA Admin',a||'@example.invalid','admin',true),(a2,o2,'QA Other Admin',a2||'@example.invalid','admin',true) on conflict(id) do update set organisation_id=excluded.organisation_id,role=excluded.role,active=true;
 insert into f values(o,o2,s,a,a2,null);
 perform public.create_notification(s,o,'Nytt gästmeddelande','synthetic','info','short-stay',null);
 perform public.create_notification(s,o,'Ny KP order','synthetic','info','kompetensportalen',null);
 perform pg_temp.expect('staff not automatically subscribed to shortstay/KP',not exists(select 1 from public.vihem_notifications where user_id=s));
 perform public.create_notification(s,o,'QA Chat','synthetic','chat','chat/qa','chat_message');
 perform public.create_notification(s,o,'QA assigned work','synthetic','info','workorders/qa','work_order_assigned');
 perform pg_temp.expect('personal defaults retained',(select count(*)=2 from public.vihem_notifications where user_id=s));
 perform public.create_notification(a,o,'Ny KP order','synthetic','info','kompetensportalen',null);
 perform pg_temp.expect('admin default retained',(select count(*)=1 from public.vihem_notifications where user_id=a));
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
end$$;
grant select,update on f to authenticated;
set local role authenticated;
do $$declare x f%rowtype;state jsonb;settings jsonb;old text;after_state jsonb;begin
 select * into x from f;
 state:=public.vihem_notification_assignment_read(x.staff);old:=state->>'revision';
 select jsonb_object_agg(k,false) into settings from unnest(public.vihem_notification_keys()) k;
 settings:=settings||'{"chat_message":true,"short_stay_new_message":true,"kompetensportalen":true}';
 after_state:=public.vihem_notification_assignment_save(x.staff,settings,old);
 perform pg_temp.expect('all types persisted',after_state->'settings'=settings);
 perform pg_temp.expect('lost response retry safe',public.vihem_notification_assignment_save(x.staff,settings,old)=after_state);
 perform pg_temp.reject('concurrent changed settings rejected',format('select public.vihem_notification_assignment_save(%L,%L::jsonb,%L)',x.staff,settings||'{"chat_message":false}',old));
 perform pg_temp.reject('unknown topic rejected',format('select public.vihem_notification_assignment_save(%L,%L::jsonb,%L)',x.staff,settings||'{"invented":true}',after_state->>'revision'));
 update f set revision=after_state->>'revision';
end$$;
reset role;
do $$declare x f%rowtype;begin select * into x from f;
 perform public.create_notification(x.staff,x.org,'Nytt gästmeddelande','synthetic','info','short-stay','short_stay_new_message');
 perform public.create_notification(x.staff,x.org,'Ny KP order','synthetic','info','kompetensportalen',null);
 perform pg_temp.expect('selected operational topics delivered',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));
 perform public.create_notification(x.staff,x.org,'QA work','synthetic','info','workorders/qa','work_order_assigned');
 insert into public.vihem_notifications(user_id,organisation_id,title,message,type,link) values(x.staff,x.org,'QA unknown','synthetic','info','unknown-feature');
 perform pg_temp.expect('disabled types and direct inserts blocked',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));
 perform public.create_notification(x.staff,x.other_org,'Cross org','synthetic','info','chat/qa','chat_message');
 perform pg_temp.expect('cross organisation notification blocked',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));
 perform set_config('request.jwt.claim.sub',x.staff::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',x.staff,'role','authenticated')::text,true);
end$$;
set local role authenticated;
select pg_temp.reject('staff cannot edit subscriptions',format('select public.vihem_notification_assignment_read(%L)',staff)) from f;
select pg_temp.reject('staff cannot access raw admin assignments','select * from public.vihem_notification_assignments');
insert into public.vihem_user_notification_settings(user_id,organisation_id,settings) select staff,org,'{"chat_message":false}' from f;
reset role;
do $$declare x f%rowtype;begin select * into x from f;perform public.create_notification(x.staff,x.org,'QA Chat','synthetic','chat','chat/qa','chat_message');perform pg_temp.expect('own mute still applies',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));end$$;
select set_config('request.jwt.claim.sub',other_admin::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',other_admin,'role','authenticated')::text,true) from f;
set local role authenticated;
select pg_temp.reject('other org admin denied',format('select public.vihem_notification_assignment_read(%L)',staff)) from f;
reset role;
update public.vihem_profiles set active=false where id=(select staff from f);
do $$declare x f%rowtype;begin select * into x from f;perform public.create_notification(x.staff,x.org,'Ny KP order','synthetic','info','kompetensportalen',null);perform pg_temp.expect('inactive recipient blocked',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));end$$;
update public.vihem_profiles set active=true where id=(select staff from f);
delete from public.vihem_user_notification_settings where user_id=(select staff from f);
select set_config('request.jwt.claim.sub',admin::text,true),set_config('request.jwt.claims',jsonb_build_object('sub',admin,'role','authenticated')::text,true) from f;
do $$declare x f%rowtype;settings jsonb;state jsonb;k text;begin
 select * into x from f;
 select jsonb_object_agg(t,false) into settings from unnest(public.vihem_notification_keys()) t;
 state:=public.vihem_notification_assignment_read(x.staff);
 perform public.vihem_notification_assignment_save(x.staff,settings,state->>'revision');
 foreach k in array public.vihem_notification_keys() loop perform public.create_notification(x.staff,x.org,'QA Category','synthetic','info','qa',k);end loop;
 perform pg_temp.expect('every category can be disabled',(select count(*)=4 from public.vihem_notifications where user_id=x.staff));
 select jsonb_object_agg(t,true) into settings from unnest(public.vihem_notification_keys()) t;
 state:=public.vihem_notification_assignment_read(x.staff);
 perform public.vihem_notification_assignment_save(x.staff,settings,state->>'revision');
 foreach k in array public.vihem_notification_keys() loop perform public.create_notification(x.staff,x.org,'QA Category','synthetic','info','qa',k);end loop;
 perform pg_temp.expect('every category can be enabled',(select count(*)=4+cardinality(public.vihem_notification_keys()) from public.vihem_notifications where user_id=x.staff));
end$$;
rollback;
